SELECT SUBSTRING_INDEX(SUBSTRING_INDEX(P.SERVE, ',', K.N), ',', -1) COD, COUNT(*) QTD FROM PRATICAS P JOIN VIDEOS V ON V.ID = P.VIDEO_ID JOIN (SELECT 1 N UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4) K ON K.N <= 1 + LENGTH(P.SERVE) - LENGTH(REPLACE(P.SERVE, ',', '')) WHERE V.STATUS = 'ESTUDADO' AND P.CONSELHO = 0 AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) AND ('{{busca}}' = '' OR CONCAT(P.TITULO, ' ', P.INSTRUCAO) COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', '{{busca}}', '%')) AND ('{{jeito}}' = '' OR P.JEITO = '{{jeito}}') AND ('{{quando}}' = '' OR FIND_IN_SET('{{quando}}', P.QUANDO)) AND P.SERVE IS NOT NULL GROUP BY COD